update public.bots
set strategy_description = 'Estratégia de price action para XAUUSD no M5. Com pelo menos 23 candles, procura um rompimento: o candle precisa fechar acima da máxima — ou abaixo da mínima — dos 20 candles anteriores e ter corpo maior que a média dos 10 candles anteriores. Depois, aguarda um pullback que reteste o nível rompido com volume não superior à média recente. A entrada só é validada por um candle de ignição na direção do rompimento, que supera a máxima ou mínima do pullback e apresenta volume acima da média dos 20 candles anteriores. Antes de sinalizar, também valida ativo, timeframe e spread máximo. O stop fica além do último fractal contrário de cinco candles, com buffer de 1 ATR(14); o alvo é calculado com risco/retorno mínimo de 1:1,5. O tamanho sugerido respeita o risco por operação configurado (5% por padrão), e a execução automática permanece bloqueada até a habilitação explícita.'
where id = 'bot-1';
